from audit_utils import *

for tree,layer in [('fr_printed','French as printed'),('fr','French corrected')]:
 rel=f'sources/{tree}/fr/212.tex'
 def r(a,b,line,kind='reading',why='',count=1):
  replace(rel,a,b,layer,'212-116',line,'7; 8','400-dpi full scan, all three enlarged bands and a tight punctuation crop. '+why,kind,count=count)
 if tree=='fr_printed':
  s,_,_=page_text(rel,116)
  for a,b,body in list(footnotes(s)):
   r(s[a:b],'','last paragraph',kind='structure',why='The correction footnote is editorial and has no printed call or text; it remains only in the corrected layer.')
  r('sur $X$.','sur $S$.','last line',why='The scan unmistakably prints S after librement sur. Restore the printed misprint in this layer.')
 else:
  with (ROOT/'CORRECTIONS.tsv').open('a',newline='') as f:
   csv.writer(f,delimiter='\t').writerow([rel,layer,'212-116','last line','8','sur $S$','sur $X$','400-dpi bottom band: the print has S. Existing correction confirmed: G is an S-group acting on X and on its invertible sheaf; the asserted freeness concerns that X-action. Its induced S-action is trivial and cannot be free for the nontrivial projective group. The existing editorial correction note is retained only here.','misprint of the original','low'])
 r('considérés par CARTIER','considéré par CARTIER','first line',why='The printed participle is singular, agreeing with passage in the previous page; it is retained in both layers.')
 for a,b,line in [('« hyperalgèbres »',r'\fquote{hyperalgèbres}','first paragraph'),('« schémas de Hilbert »',r'\fquote{schémas de Hilbert}','section 8 introduction'),('« unités »',r'\fquote{unités}','multiplicative group paragraph')]:
  r(a,b,line,why='Ordinary double quotation marks.')
 r(r'\fsection{8}{Une conjecture}',r'\fsection{\normalfont 8}{\normalfont\uline{Une conjecture}.}','section 8 heading',why='Roman heading, straight-underlined title and final period.')
 r('À tout préschéma','A tout préschéma','matrix group introduction',why='The initial capital A has no accent in the scan.')
 r(r'noté $\operatorname{Gl}(n)_S$',r'noté $G\ell(n)_S$','first naming of the group scheme',why='The l is handwritten cursive at this occurrence, unlike the typed Gl in the pointwise matrix group.')
 r('noté\n'+r'$\operatorname{Gl}(n)$',r'noté $G\ell(n)$','group over the integers',why='This second named group also uses a cursive ell. Subsequent typed Gl occurrences are retained.')
 r(r'\emph{groupe projectif de degré $n-1$ sur $\mathbf Z$}',r'\uline{groupe projectif de degré} $n-1$ \uline{sur} $\mathbf Z$','projective group definition',why='Only the prose spans are straight-underlined; the formulas have their own printed letterforms.')
 r(r'\mathbf Z',r'\text{\uwave{Z}}','two integer-base symbols',count=2,why='Z has a wavy underline, not boldface.')
 r(r'\mathbf G_m',r'G_m','multiplicative group symbol',why='G is ordinary upright, not bold.')
 r(r'\mathbf P_S',r'P_S','projective-space symbols',count=2,why='P is ordinary typed upright, not bold.')
 r(r'\longmapsto',r'\rightsquigarrow','two functor arrows',count=2,why='Both functor arrows are wavy arrows in the print.')
 r(r'\widetilde{\operatorname{Gl}(n)}_S',r'\text{\uwave{Gl}}(n)_S','section sheaf symbols',count=2,why='The wave is beneath Gl only, not a tilde above the whole expression.')
 r(r'\widetilde{\operatorname{Gl}(1)}_S',r'\text{\uwave{Gl}}(1)_S','denominator sheaf symbol',why='The wave is beneath Gl only.')
 r(r'\emph{librement}',r'\uline{librement}','last line',why='The word is straight-underlined; sur and the following base symbol are outside the underline.')
 upright_page(rel,layer,'212-116')

event('212-7-hyperalgebras','carried as background without fault found','The historical interpretation of Cartier hyperalgebras through formal group schemes, with the finite-rank case giving finite algebraic group schemes, is retained. A precise modern correspondence needs the appropriate dual Hopf algebra and completeness hypotheses; no unqualified identification with every arbitrary Hopf algebra is inferred from this short paragraph.','212, p. 116, opening paragraph')
event('212-8-GL','independent re-proof','For n at least one, GL(n) is represented by Spec Z[x_ij,det(x)^(-1)]. Giving a morphism from any scheme T to this affine scheme is giving global sections x_ij with invertible determinant, exactly an invertible n by n matrix over Gamma(T,O_T). Matrix multiplication and the adjugate-over-determinant inverse define its group structure. Tensoring the coordinate ring with a base ring, or taking its relative Spec, proves arbitrary base compatibility. For n=1 this is Spec Z[t,t^(-1)], representing global units. The implicit positive-rank convention is left unchanged in the historical wording.','212, p. 116, matrix and multiplicative group construction')
event('212-8-projective-group','independent re-proof','Let P be projective space on the n squared matrix entries over Z. The open D_+(det) represents matrices up to invertible scalar locally on the base. GL(n) to this open is a Zariski locally trivial G_m-torsor: on an open where an entry is a generator, divide all entries by that entry. Matrix multiplication and adjugate inversion are independent of the chosen local scalar and glue to a group structure. Thus this open represents the Zariski sheaf quotient of GL(n) by scalars, with the notation GP(n-1) used by the print. It is affine because D_+(det) is a standard affine open of Proj. This directly verifies the sheaf-of-sections description without replacing it by the generally incorrect quotient of global sections.','212, p. 116, definition of GP(n-1)')
event('212-8-projective-lifting','independent re-proof','Explicit nonlifting example for n=2: take R=Z[s]/(s^2+5), and I=(2,1+s). One has I^2=(2): the generators 4,2+2s,-4+2s are multiples of 2 and their combinations contain 2. Hence I is invertible. It is not principal: R/I has two elements, whereas a principal generator a+b s would have index a^2+5b^2, which cannot equal two. The matrix with rows (2,1+s) and (1-s,2) has all entries in I and determinant -2, a generator of I^2. It therefore gives an isomorphism R^2 to I direct-sum I. Trivializing I locally turns it into invertible matrices differing on overlaps by scalar units, hence a section of GP(1). A global GL(2) lift would trivialize the associated scalar line bundle I, contradiction. This checks the printed warning that projective sections need not lift globally.','212, p. 116, parenthetical lifting warning')
event('212-8-projective-automorphisms','carried as background without fault found','Identification of GP(n-1) with automorphisms of projective (n-1)-space requires that an automorphism preserves O(1) up to tensoring by a line bundle from the base; pushing forward O(1) then produces the locally scalar matrix class. The needed relative Picard and cohomology facts, including their applicability over a noetherian base, are identified as background. The elementary matrix quotient proof above does not by itself prove this full automorphism assertion.','212, p. 116, automorphism functor paragraph')
event('212-8-free-action-base','targeted proof check','The final printed S is a misprint for X. The preceding data are an action of the S-group GP(n)_S on the S-prescheme X and a compatible action on its line bundle. The induced action on the base S is trivial; for a nontrivial projective group it cannot be free. The intended freeness of the action on X is also the condition used in the subsequent quotient conjecture. Confirmed the existing correction and kept its editorial footnote only in the corrected layer.','212, p. 116, final sentence')
record_page('212',116,r'''Compared sources/fr_printed/fr/212.tex entry lines 790–837 and sources/fr/fr/212.tex entry lines 795–842 with scan leaf 19 at 400 dpi, full page and all three enlarged bands, plus a tight crop of qui, à S, associe. The tiny isolated ink speck above that comma does not justify changing it to a semicolon; the comma is retained provisionally for the second reading.

Confirmed the existing final S-to-X correction from the image and the action’s domain. The as-printed layer restores S and removes the editorial note; the corrected layer retains X and the explicit existing correction note. Both layers restore the singular considéré, unaccented capital A, ordinary quotes, the roman underlined section heading, two local cursive ell forms in the names of GL, wavy-underlined Z and Gl sheaf symbols, ordinary G and P, wavy functor arrows, exact underline spans and upright mathematics. The printed script L and O forms are retained.

Verified GL and the projective scalar quotient directly, including an explicit invertible-ideal example showing that a projective matrix need not lift to a global matrix. The projective-space automorphism identification and the historical hyperalgebra correspondence are retained with their remaining background inputs stated. The conjecture’s assertion continues on the next page.''')
